for (const [name,id,items] of extraTopics) {
  topics.push({id,name,icon:'road',facts:items.map(([q,a,e])=>[q,a,[],e])});
}

const distractors = {
  'Yes':['No','Only at night','Only on motorways'],
  'No':['Yes','Only for learners','Only when raining']
};

function makeOptions(answer, wrongs, index) {
  const pool = wrongs?.length ? wrongs : [
    'Only when traffic is heavy','It is optional','Only for learner drivers'
  ];
  const unique = [...new Set([answer,...pool])].slice(0,4);
  while(unique.length<4) unique.push(`Another option ${unique.length}`);
  const correct = unique.indexOf(answer);
  return {options:unique, answer:correct};
}

const questionBank = [];
let counter = 1;
for (const topic of topics) {
  topic.facts.forEach((fact, i) => {
    const [q,a,wrongs,ex] = fact;
    const fallback = distractors[a] || [
      'Only in exceptional circumstances','A different road rule applies','It is never necessary'
    ];
    const built = makeOptions(a, [...(wrongs||[]), ...fallback], i);
    questionBank.push({
      id: counter++, topicId: topic.id, category: topic.name, question:q,
      options:built.options, answer:built.answer, explanation:ex,
      image:`/assets/topics/${topic.icon}.svg`, difficulty: i%3===0?'Easy':i%3===1?'Medium':'Hard'
    });
  });
}

// Ensure exactly 500 questions. The first 20 facts in each of 25 topics form the core bank.
const selectedQuestions = questionBank.slice(0,500);
export const TOPICS = topics.map(({facts,...t})=>({...t,count:selectedQuestions.filter(q=>q.topicId===t.id).length})).filter(t=>t.count>0);
export const THEORY_CHAPTERS = TOPICS.map(t => ({
  id:t.id, title:t.name, summary:`Study ${t.name.toLowerCase()} with key rules, practical explanations and exam-focused questions.`,
  points: selectedQuestions.filter(q=>q.topicId===t.id).slice(0,5).map(q=>q.question)
}));
export default selectedQuestions;
